import sys, re
sys.path.insert(0, sys.argv[1]); from po import parse
path = sys.argv[2]; tfiles = sys.argv[3:]
tr = {}; notes = {}
for tf in tfiles:
    for line in open(tf, encoding='utf-8').read().split('\n'):
        if not line.strip(): continue
        key, text = line.split('\t', 1)
        if key.endswith('!'): notes[int(key[:-1])] = text; continue
        if '.' in key:
            k, f = key.split('.'); tr.setdefault(int(k), {})[int(f)] = text
        else: tr[int(key)] = text
        if re.search(r'(?<!\\)"', text): print('UNESCAPED QUOTE', key, text)
lines, ents = parse(path)
out = list(lines); inserts = {}
missing = []
for k, e in enumerate(ents):
    if e['id'] == '': continue
    if k not in tr: missing.append(k); continue
    t = tr[k]
    for li in e['msgstr_lines']:
        l = out[li]
        if l.startswith('msgstr['):
            n = int(l[7:l.index(']')]); out[li] = f'msgstr[{n}] "{t[n]}"'
        elif l.startswith('msgstr '):
            assert isinstance(t, str), k; out[li] = f'msgstr "{t}"'
        else: out[li] = None  # continuation of msgstr
    if not any(c.strip() == '# AI Translated' for c in e['comments']):
        first = e['start']
        while out[first].startswith('# ') or out[first] == '#': first += 1
        ins = ['# AI Translated'] + ([f'# Needs human review: {notes[k]}'] if k in notes else [])
        inserts[first] = ins
res = []
for i, l in enumerate(out):
    if i in inserts: res.extend(inserts[i])
    if l is not None: res.append(l)
open(path, 'w', encoding='utf-8').write('\n'.join(res))
print('missing', len(missing), missing[:20]); print('translated', len(tr), 'notes', len(notes))
EOF
echo

